head.script:
scwin.getType = function(info) {
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var returnInfo;
    if (dataList1.getCellData(rowIndex, "col2") == 1) {
        returnInfo = {
            id: "dynamic_radio_" + rowIndex + "_" + colIndex,
            inputType: "radio",
            options: {}
        };
    } else {
        returnInfo = {
            id: "dynamic_text_" + rowIndex + "_" + colIndex,
            inputType: "text"
        };
    }
    if (returnInfo) {
        //console.log( "[typeGetter] (" + rowIndex + ", " + colIndex + ") : " +returnInfo.inputType);
    }
    return returnInfo;
};
scwin.grd_onviewchange = function(info) {
    grd.refreshRow(info.rowIndex);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

scwin.trigger1_onclick = function(e) {
    console.log(dataList1.getAllArray().data);
    log = dataList1.getAllArray().data;
    //alert(dataList1.getAllArray().data);
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 name1항목의 첫번째 radio버튼을 클릭하고 두번째 radio버튼을 클릭한 후 'dataList1.getAllArray().data'버튼을 클릭한다.
    //1. After running the sample, click the first radio button in the name1 item, click the second radio button, and click the 'dataList1.getAllArray (). Data' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_cell_0_0').childNodes[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_cell_1_0').childNodes[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 알림창에 '0,1,,1,1,,,1,,,2,,,a3,,,1,'값이 보여진다.(이전에는 첫번째에 선택된 radio의 값이 남아있어서 '1,1,,1,1,,,1,,,2,,,a3,,,1,'값으로 보여짐)
    //1. '0, 1,, 1,1 ,,, 1 ,,, 2 ,,, a3 ,,,,,,,,,, value are shown in the information window.(Previously, the value of the radio selected at the first time remains and is shown as '1,1, 1,1 ,,, 1 ,,, 2 ,,, a3 ,,,,,'
    WebSquare.wUnit.addCommand("assert", "log.toString() == '0,1,,1,1,,,1,,,2,,,a3,,,1,'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "col2": "1"
    }, {
        "col2": "1"
    }, {
        "col2": "1"
    }, {
        "col2": "2"
    }, {
        "col2": "a3"
    }, {
        "col2": "1"
    }];
    dataList1.setJSON(jsonData);
    window.jsonData2 = [{
        "col1": "a1",
        "col2": "a1"
    }, {
        "col1": "a2",
        "col2": "a2"
    }, {
        "col1": "a3",
        "col2": "a3"
    }];
    dataList2.setJSON(jsonData2);
    window.log = undefined;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 22-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
